{
  "scratchpad": "I'm the platform engineer (ops). My job is to publish reports and manage outbound integrations. The team needs to create reports/weekly.md with total revenue from orders table, then POST it to the dashboard API. I should start by understanding the report format from README, then coordinate with analyst to draft the report and writer to review it before I publish.",
  "actions": [
    {"tool": "read_file", "args": {"path": "reports/README.md"}},
    {"tool": "send_message", "args": {"to": "analyst", "content": "Hi! I'm ops, the platform engineer. We need to produce this week's revenue report at reports/weekly.md with total revenue from the orders table. Can you query the database and draft the initial report? Once you have a draft, I'll have the writer review it before I publish to the dashboard."}}
  ],
  "done": false
}
